// VULNERABLE — echoes raw user input into HTML
echo "You searched for: " . $_GET['q'];

// SAFE — HTML-encode before output
echo "You searched for: " . htmlspecialchars($_GET['q'], ENT_QUOTES, 'UTF-8');

// VULNERABLE — reads hash fragment and writes to DOM as HTML
const name = decodeURIComponent(location.hash.slice(1));
document.getElementById('greeting').innerHTML = 'Hello, ' + name;
// Payload: https://example.com/page#<img src=x onerror=steal()>

// SAFE — use textContent, not innerHTML
document.getElementById('greeting').textContent = 'Hello, ' + name;

// React — SAFE: JSX escapes by default
const UserGreeting = ({ name }) => <div>Hello, {name}</div>;

// React — DANGEROUS: explicit bypass, only use for trusted HTML
const RichContent = ({ html }) => (
  <div dangerouslySetInnerHTML={{ __html: html }} />
);
// If `html` contains attacker-controlled content, this is stored XSS.

// Angular — SAFE: template interpolation {{ value }} auto-escapes
// Angular — DANGEROUS: bypassSecurityTrustHtml() opts out of sanitization

# Nonce-based strict CSP — generated per response
Content-Security-Policy:
  default-src 'none';
  script-src 'nonce-{RANDOM_BASE64}' 'strict-dynamic';
  style-src 'nonce-{RANDOM_BASE64}';
  img-src 'self';
  font-src 'self';
  connect-src 'self';
  base-uri 'none';
  form-action 'self';
  frame-ancestors 'none';

// Define a Trusted Types policy
const policy = trustedTypes.createPolicy('myPolicy', {
  createHTML: (input) => DOMPurify.sanitize(input),  // sanitize, then wrap
  createScriptURL: (url) => {
    if (url.startsWith('https://cdn.example.com/')) return url;
    throw new Error('URL not allowed');
  }
});

// Usage — only TrustedHTML objects accepted; strings throw TypeError
element.innerHTML = policy.createHTML(userInput);  // OK
element.innerHTML = userInput;                       // TypeError — blocked

# XSS — nonce-based strict CSP; Trusted Types enforcement
Content-Security-Policy:
  default-src 'none';
  script-src 'nonce-{PER_REQUEST_NONCE}' 'strict-dynamic';
  style-src 'nonce-{PER_REQUEST_NONCE}';
  img-src 'self' data:;
  connect-src 'self';
  font-src 'self';
  base-uri 'none';
  form-action 'self';
  frame-ancestors 'none';
  require-trusted-types-for 'script';
  report-to csp-endpoint;

# Clickjacking — belt-and-suspenders
X-Frame-Options: DENY

# Sniffing attacks
X-Content-Type-Options: nosniff

# Cross-origin isolation (if SharedArrayBuffer / high-res timers needed)
Cross-Origin-Opener-Policy: same-origin
Cross-Origin-Embedder-Policy: require-corp

# HSTS — enforce HTTPS, prevent cookie interception
Strict-Transport-Security: max-age=63072000; includeSubDomains; preload
